Rules.InvariantScript:
//Set(var_usuarioID; "");;
ClearCollect(
    col_menuModulos,
    Filter(
        tbl_Modulos,
        Titulo = "Inspeção de pista" Or Titulo = "Inspeção de Pátio" Or Titulo = "Inspeção TPS"
    )
);
ClearCollect(
    col_NavTelas,
    {
        Id: 28,
        TelaListar: frmHomePista
    },
    {
        Id: 60,
        TelaListar: frmHomePatio
    },
    {
        Id: 64,
        TelaListar: frmHomeTPS
    }
);

ClearCollect(
    col_ZPASobstaculos,
    First(tbl_inspZPAitens)
);
Clear(col_ZPASobstaculos);
Navigate(
    frmFormZPA,
    ScreenTransition.Fade,
    {var_zpa_acao: "cad"}
);
Set(
    var_idItensZPA,
    0
);
ResetForm(FormZpa);
NewForm(FormZpa);
Reset(AddMediaButtonD3);
Reset(AddMediaButtonD2);
Reset(AddMediaButtonD1);
Reset(AddMediaButtonE3);
Reset(AddMediaButtonE2);
Reset(AddMediaButtonE1)

Navigate(
    frmZPAapontamentos,
    ScreenTransition.Fade,
    {
        var_consultaItensInspecao: Blank(),
        var_idSelectItem: 0
    }
)

ForAll(
    Distinct(
        Filter(
            colAeros,
            Bloco = cmbHomeBloco_8.Selected.Value
        ),
        Aeroporto
    ),
    {Result: ThisRecord.Value}
)

Reset(cmbHomeBloco_8);
Reset(cmbHomeAeroporto_8);
Reset(txtLimit_3);
Reset(dtpHomeDtfInicio_8);
Reset(dtpHomeDtfTermino_8);
Reset(cmbHomeStatus_6);
Reset(txtBuscarInspPatio_2)

FirstN(
    //Search(
        Sort(
            Sort(
                Filter(
                    tbl_inspZpa,
                    StartsWith(
                        Aeroporto,
                        Text(cmbHomeAeroporto_8.Selected.Result)
                    ),
                    StartsWith(
                        Bloco,
                        Text(cmbHomeBloco_8.Selected.Value)
                    ),
                    StartsWith(
                        Status,
                        cmbHomeStatus_6.Selected.Value
                    ),
                    Periodo = Last(
                        Split(
                            var_tituloModulo,
                            " "
                        )
                    ).Value,
                    Inicio >= dtpHomeDtfInicio_8.SelectedDate && Termino <= dtpHomeDtfTermino_8.SelectedDate,
                    IsBlank(txtBuscarInspPatio_2.Text) || ID = Value(txtBuscarInspPatio_2.Text)
                ),
                Status,
                SortOrder.Ascending
            ),
            ID,
            SortOrder.Descending
        ),/*
        txtBuscarInspPatio_2.Text;
        Inspetor1;
        Inspetor2
    );*/
    Value(txtLimit_3.Text)
)

If(
    IsBlank(ThisItem.Status) Or ThisItem.Status = "Em andamento",
    Set(
        var_visibleHome,
        false
    );
    UpdateContext(
        {
            var_visibleInspPatiocad: true,
            var_visibleInspPatiocad1: true,
            var_visibleInspPatiocad2: false,
            var_visibleInspPatiocadMenu: false,
            var_acao: "Continuar",
            Var_IDinspTPS: ThisItem.ID,
            var_status: ThisItem.Status
        }
    );
    EditForm(FormInspTPS)
)

Navigate(
    frmFormZPAeditar,
    ScreenTransition.Fade,
    {
        var_zpa_acao: "edit",
        var_zpa_dados: LookUp(
            tbl_inspZpa,
            ID = ThisItem.ID
        )
    }
);
EditForm(FormZpaEdit)

ControlPropertyState.AutoRuleBindingString:
Navigate(
    frmFormZPAeditar,
    ScreenTransition.Fade,
    {
        var_zpa_acao: "edit",
        var_zpa_dados: LookUp(
            tbl_inspZpa,
            ID = ThisItem.ID
        )
    }
);
EditForm(FormZpaEdit)

Rules.InvariantScript:
Set(
    var_visibleHome,
    true
);
UpdateContext(
    {
        var_visibleExcluir: false,
        var_visibleInspPatio: true
    }
)

Set(
    var_visibleHome,
    true
);
UpdateContext(
    {
        var_visibleExcluir: false,
        var_visibleInspPatio: true
    }
);
Concurrent(
    RemoveIf(
        tbl_inspTPSitens,
        ID_insp = var_itemExluir.ID
    ),
    RemoveIf(
        tbl_inspTPS,
        ID = var_itemExluir.ID
    )
);
Notify(
    "A inspeção e todos os Itens vinculados foram excluidos com sucesso!",
    NotificationType.Success
)

RemoveIf(
    tbl_inspZPAitens,
    ID_FK = var_itemExluir.ID
);
RemoveIf(
    tbl_inspZPAfotos,
    ID_FK = var_itemExluir.ID
);
Remove(
    tbl_inspZpa,
    var_itemExluir
);
UpdateContext({var_visibleExcluirInspZpa: false});
Notify(
    "Inspeção removida com sucesso!",
    NotificationType.Success
)
